if (info.rle) {
    char *dst = (char *)image;
    qint64 num = size;

    while (num > 0) {
        if (s.atEnd()) {
            valid = false;
            break;
        }
        uchar c;
        s >> c;
        uint count = (c & 0x7f) + 1;
        num -= count * pixel_size;
        if (num < 0) {
            valid = false;
            break;
        }
        if (c & 0x80) {
            assert(pixel_size <= 8);
            char pixel[8];
            s.readRawData(pixel, pixel_size);
            do {
                memcpy(dst, pixel, pixel_size);
                dst += pixel_size;
            } while (--count);
        } else {
            count *= pixel_size;
            s.readRawData(dst, count);
            dst += count;
        }
    }
}
```

